import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("Claim Office — quote", () => {
  describe("edge cases", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
  });

  describe("main item base premiums (newcomer: +10% first insurance, +5 G fee)", () => {
    it.todo("plain sword, 0 years → 100 + 10 + 5 = 115 G");
    it.todo("plain amulet, 0 years → 60 + 6 + 5 = 71 G");
    it.todo("plain staff, 0 years → 80 + 8 + 5 = 93 G");
    it.todo("plain potion, 0 years → 40 + 4 + 5 = 49 G");
  });

  describe("components and building blocks", () => {
    it.todo("2 runes → 50 G base premium → 55 + 5 = 60 G");
    it.todo("3 runes → 60 G base premium (block) → 66 + 5 = 71 G");
    it.todo("4 runes → 100 G base premium (no block, block requires exactly 3) → 110 + 5 = 115 G");
    it.todo("7 runes → 175 G base premium → 192.5 + 5 = 197.5 → rounded up 198 G");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types) → 82.5 + 5 → 88 G");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks) → 132 + 5 = 137 G");
  });

  describe("item-specific modifiers", () => {
    it.todo("newcomer with cursed steel sword, enchantment 3 → 165 G");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge → 115 G");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies → (100+30)+10+5 = 145 G");
    it.todo("cursed sword with enchantment 5 → both surcharges → (100+50+30)+10+5 = 195 G");
    it.todo("cursed sword + plain amulet → surcharge only on sword's base: 210 G + 16 first insurance + 5 fee = 231 G");
  });

  describe("policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years → loyalty discount applies: plain sword → 100 − 20 + 10 + 5 = 95 G");
    it.todo("customer with 1 year → no loyalty discount: plain sword → 115 G");
    it.todo("second quote in a scenario gets 15% follow-up discount: plain sword → 100 + 10 − 15 + 5 = 100 G");
    it.todo("long-standing customer's second contract, cursed sword enchantment 7 → 160 G (first insurance still applies)");
  });
});

describe("Claim Office — claim", () => {
  describe("standard reimbursement", () => {
    it.todo("regular steel sword enchantment 3, damage 500 G → payout 400 G, remainingCap 1600 G");
    it.todo("rune damaged 200 G → payout 100 G");
    it.todo("amulet damage 200 G (schema example) → payout 100 G, remainingCap 1100 G");
  });

  describe("enchantment and dragon material clauses", () => {
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G");
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50% rule wins)");
    it.todo("dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G");
  });

  describe("deductible per damage event", () => {
    it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G");
    it.todo("two insured swords both damaged → each entry has its own deductible");
  });

  describe("rounding", () => {
    it.todo("payout yielding 350.5 G is rounded down to 350 G (enchantment ≥ 8 sword, damage 901 G)");
  });

  describe("cap", () => {
    it.todo("sword + amulet policy → cap 3200 G (remainingCap after small claim reflects it)");
    it.todo("two swords → cap 4000 G");
    it.todo("cursed sword → cap 2000 G based on unmodified insurance value");
    it.todo("sword + 3 runes (block) → insurance sum 1750 G, cap 3500 G");
    it.todo("two successive 1500 G claims on a sword → 1400 G (cap 600), then 600 G (cap 0)");
  });

  describe("errors", () => {
    it.todo("quote with unknown item type (broomstick) throws");
    it.todo("claim for an item not in the policy (amulet when only sword insured) throws");
    it.todo("claim for an unknown item type throws");
    it.todo("claim with negative damage amount (-200) throws");
    it.todo("claim with more damage entries of a type than insured (two swords, one insured) throws");
  });
});

describe("claim-office CLI", () => {
  it.todo("reads the schema example scenario from stdin and writes results JSON to stdout");
  it.todo("unknown item type → non-zero exit, error on stderr, no results on stdout");
  it.todo("negative damage amount → non-zero exit, error on stderr");
});

