export type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };

export type QuoteStep = { op: "quote"; items: Item[] };

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};

export type Result = { premium: number } | { payout: number; remainingCap: number };

export type ScenarioOutcome = { results: Result[] };

const BASE_PREMIUMS: Record<string, number> = {
  // main items
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  // components (priced per piece)
  rune: 25,
};
const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

// Integer-percent arithmetic avoids floating-point drift (e.g. 115.00000000000001).
const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;

const sumBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const quotePremium = (items: Item[]): number => {
  const basePremium = sumBasePremiums(items);
  return basePremium + percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT) + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  results: [{ premium: quotePremium(scenario.steps[0].items) }],
});

