const BASE_PREMIUMS: Record<string, number> = {
  // main items
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  // components (priced per piece)
  rune: 25,
  moonstone: 25,
};
// A full block of components is priced as a unit instead of per piece.
const COMPONENTS_PER_BLOCK = 3;
const COMPONENT_BLOCK_PREMIUM = 60;
const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

// Integer-percent arithmetic avoids floating-point drift (e.g. 115.00000000000001).
const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;

const formsRuneBlock = (items: Item[]): boolean =>
  items.filter((item) => item.type === "rune").length === COMPONENTS_PER_BLOCK;

const sumBasePremiums = (items: Item[]): number => {
  if (formsRuneBlock(items)) return COMPONENT_BLOCK_PREMIUM;
  return items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
};

// Premiums are rounded in MHPCO's favor; only the final amount is rounded.
const roundUpInMHPCOsFavor = (amount: number): number => Math.ceil(amount);

const quotePremium = (items: Item[]): number => {
  const basePremium = sumBasePremiums(items);
  const firstInsuranceSurcharge = percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
  return roundUpInMHPCOsFavor(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
};

