const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const HIGH_ENCHANTMENT_THRESHOLD = 5;

// Integer-percent arithmetic avoids floating-point drift (e.g. 115.00000000000001).
const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;

const basePremiumForType = (type: string, count: number): number => {
  if (COMPONENT_TYPES.includes(type) && count === COMPONENTS_PER_BLOCK) return COMPONENT_BLOCK_PREMIUM;
  return count * BASE_PREMIUMS[type];
};

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  return counts;
};

